def remove_target(stack, target, make_stack):
    temp = make_stack()
    removed = None
    while not stack.isEmpty():
        item = stack.pop()
        if item.identifier == target:
            removed = item
            break
        temp.push(item)
    while not temp.isEmpty():
        stack.push(temp.pop())
    return removed

